insert into public.notes (id, organization_id, title, body, client_id, project_id, contact_id, opportunity_id, created_at, updated_at) values
  ('note_001', 'org_demo', 'Négociation NovaRetail', 'Sophie Garnier souhaite un engagement de 24 mois en échange d''une remise de 8 %. À arbitrer au prochain comité.', 'cli_novaretail', null, 'con_novaretail_sophie', 'opp_nova_multisite', '2026-10-17T17:00:00.000Z', '2026-10-17T17:00:00.000Z'),
  ('note_004', 'org_demo', 'Contexte Helios', 'Projet porté par la direction générale ; trois sites pilotes. Concurrence : un éditeur spécialisé énergie.', 'cli_helios', null, 'con_helios_margaux', 'opp_helios_cadrage', '2026-10-08T17:00:00.000Z', '2026-10-08T17:00:00.000Z'),
  ('note_005', 'org_demo', 'Préférences de contact', 'Préfère être contacté par e-mail le matin ; éviter les relances le vendredi.', 'cli_vectis', null, 'con_vectis_anne', null, '2026-10-05T17:00:00.000Z', '2026-10-05T17:00:00.000Z'),
  ('note_006', 'org_demo', 'Satisfaction GreenPulse', 'Délais de support jugés trop longs au dernier comité. Proposer le Support Premium.', 'cli_greenpulse', null, 'con_greenpulse_claire', null, '2026-10-15T17:00:00.000Z', '2026-10-15T17:00:00.000Z'),
  ('note_007', 'org_demo', 'Partenariat Nexus', 'Intégrateur intéressé par une revente de BDO Flow. Prévoir une grille de commissions.', 'cli_nexus', null, 'con_nexus_thomas', null, '2026-09-25T17:00:00.000Z', '2026-09-25T17:00:00.000Z'),
  ('note_002', 'org_demo', 'Risques PRJ-006', 'Le connecteur ERP a consommé 236 h pour 160 h prévues. Prévoir un avenant ou une revue du périmètre de l''assistant IA.', 'cli_orbis', 'prj_006', null, null, '2026-10-12T18:00:00.000Z', '2026-10-12T18:00:00.000Z'),
  ('note_003', 'org_demo', 'Idées pour 2027', 'Packager BDO Flow + BDO Automation en offre « Opérations augmentées ». Étudier un programme partenaires intégrateurs.', null, null, 'con_nexus_thomas', null, '2026-10-05T19:00:00.000Z', '2026-10-05T19:00:00.000Z');
